{"explanation":"A secant line joins two points on a curve: P at x = 1 and Q at x = 1 + h. As h approaches zero, Q approaches P and the secant slope approaches the tangent slope. For f(x) = x²/2, the secant slope is 1 + h/2, which approaches f′(1) = 1. Use the slider to explore the approach from either side.","manimCode":"const heading = new Text({ text: 'From secant to tangent', fontSize: 34, color: WHITE });
heading.moveTo([0, 3.15, 0]);
const equation = new MathTex({ latex: '\\frac{f(1+h)-f(1)}{h}=1+\\frac{h}{2}\\;\\longrightarrow\\;f\'(1)=1' });
await equation.waitForRender();
equation.scale(0.8);
equation.moveTo([0, 2.35, 0]);
const ax = new Axes({ xRange: [-1, 3, 1], yRange: [-2, 5, 1], xLength: 8.6, yLength: 4.3, tips: false });
ax.moveTo([0, -0.45, 0]);
const fn = x => x * x / 2;
const curve = ax.plot(fn, { color: BLUE, xRange: [-1, 3], numSamples: 200 });
const tangent = ax.plot(x => x - 0.5, { color: GREEN, xRange: [0, 2.6] });
tangent.setStrokeWidth(5);
tangent.setOpacity(0.55);
const hTracker = new ValueTracker(1.5);
const pDot = new Dot({ point: ax.c2p(1, fn(1)), color: WHITE });
const qDot = new Dot({ point: ax.c2p(2.5, fn(2.5)), color: YELLOW });
const secant = new Polygon({ vertices: [ax.c2p(0, -1.25), ax.c2p(2.6, 3.3)], color: YELLOW });
secant.setFillOpacity(0);
secant.setStrokeWidth(3);
secant.addUpdater(mob => {
  const slope = 1 + hTracker.getValue() / 2;
  mob.setVertices([ax.c2p(0, 0.5 - slope), ax.c2p(2.6, 0.5 + 1.6 * slope)]);
});
qDot.addUpdater(mob => {
  const qx = 1 + hTracker.getValue();
  mob.moveTo(ax.c2p(qx, fn(qx)));
});
const pLabel = new Text({ text: 'P', fontSize: 22, color: WHITE });
pLabel.moveTo(ax.c2p(1, 0.5));
pLabel.shift([-0.28, -0.3, 0]);
const qLabel = new Text({ text: 'Q', fontSize: 22, color: YELLOW });
qLabel.addUpdater(mob => {
  const qx = 1 + hTracker.getValue();
  mob.moveTo(ax.c2p(qx, fn(qx)));
  mob.shift([0.24, 0.24, 0]);
});
const curveLabel = new Text({ text: 'f(x) = x²/2', fontSize: 22, color: BLUE });
curveLabel.moveTo([-3.1, 1.4, 0]);
const legend = new Text({ text: 'Yellow: secant     Green: tangent', fontSize: 22, color: WHITE });
legend.moveTo([0, -3.05, 0]);
await scene.play(new Write(heading), new Write(equation));
await scene.play(new Create(ax), new Create(curve));
scene.add(tangent, secant, pDot, qDot, pLabel, qLabel, curveLabel, legend);
await scene.wait(0.8);
await scene.play(hTracker.animateTo(0.03));
await scene.wait(0.6);
const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({ label: 'h (0 gives the tangent limit)', min: -1.5, max: 1.5, value: 0.03, step: 0.01, onChange: value => { hTracker.setValue(value); } });
controls.addButton({ label: 'Tangent limit: h = 0', onClick: () => { hTracker.setValue(0); } });
makeHoverable(pDot, scene, { hoverScale: 1.4 });
makeHoverable(qDot, scene, { hoverScale: 1.4 });
await scene.wait(999999);"}

